export const syncActiveSystemPlanetLogisticsConfig = (systemKey: string): void => {
  const assign = getStarSystemFullAssignment(systemKey);
  const romans = ['I', 'II', 'III', 'IV'] as const;
  for (let i = 0; i < 4; i++) {
    const p = assign.planets[i];
    if (p && PLANET_LOGISTICS_CONFIG[i]) {
      PLANET_LOGISTICS_CONFIG[i].cleanName = `${p.officialName} («${p.folkName}»)`;
      PLANET_LOGISTICS_CONFIG[i].shortTag = `${romans[i]}. ${p.officialName.toUpperCase()} («${p.folkName.toUpperCase()}»)`;
    }
  }
};

export const getPlanetResourceInfo = (
  planetIdx: number,
  isOldGalaxy: boolean
): {symbol: AsteroidElementSymbol; title: string; planetName: string; color: string} => {
  const cfg = PLANET_LOGISTICS_CONFIG[planetIdx] || PLANET_LOGISTICS_CONFIG[0];
  if (isOldGalaxy) {
    return {
      symbol: 'Omega',
      title: 'Критическое вещество (Ω-γ)',
      planetName: `Реликтовый узел #${cfg.planetOrder}`,
      color: '#e879f9',
    };
  }
  return {
    symbol: cfg.resourceSymbol,
    title: cfg.resourceTitle,
    planetName: cfg.cleanName,
    color: cfg.color,
  };
};

