interface SystemPlanet {
  id: string;
  name: string;
  cleanName: string;
  shortMarker: string;
  specializationShort: string;
  orbitOrder: number; // 1..4 (Меркурий, Венера, Земля, Марс)
  orbitRadius: number; // 6000, 12000, 18000, 24000 (ровно 6000 ед = 1 минута полёта на макс. скорости 100 ед/с!)
  orbitAngle: number;
  orbitSpeed: number;
  radius3D: number;
  spinAngle: number;
  spinSpeed: number; // Замедлено в 3 раза для удобного взаимодействия с объектами GoBell на планете!
  color: string;
  labelOffsetY: number;
  isMainWorld?: boolean;
  isDeathStar?: boolean;
  isTorusShip?: boolean;
  isStargate?: boolean;
  isBuranShuttle?: boolean;
  isKuiperBelt?: boolean;
  kuiperMeta?: KuiperBeltBodyDef;
  shapeType?: 'SPHERE' | 'ELLIPSOID' | 'CONTACT_BINARY';
  ellipsoidScale?: {x: number; y: number; z: number};
  hasRings?: boolean;
  ringRadiusRatio?: number;
  ringColor?: string;
  isRocheLimitAnomaly?: boolean;
  hasHeartFeature?: boolean;
  isSnowmanContactBinary?: boolean;
  kuiperMoons?: KuiperMoonDef[];
  isJupiter?: boolean;
  jupiterMeta?: JupiterPlanetDef;
  galileanMoons?: Array<{
    def: GalileanMoonDef;
    orbitAngle: number;
  }>;
  isSaturn?: boolean;
  saturnMeta?: SaturnPlanetDef;
  saturnMoons?: Array<{
    def: SaturnMoonDef;
    orbitAngle: number;
  }>;
  isUranus?: boolean;
  uranusMeta?: UranusPlanetDef;
  uranusMoons?: Array<{
    def: UranusMoonDef;
    orbitAngle: number;
  }>;
  isNeptune?: boolean;
  neptuneMeta?: NeptunePlanetDef;
  neptuneMoons?: Array<{
    def: NeptuneMoonDef;
    orbitAngle: number;
  }>;
  gobellObjects: PlanetGoBellObject[];
}

